begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Native report source fixture','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)select'10000000-0000-4000-8000-000000000001',('98010000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'98000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Report task '||i,'School authored',10,'61000000-0000-4000-8000-000000000001'from generate_series(1,2)i;
insert into app.submissions(school_id,id,assessment_id,learner_id,content)select'10000000-0000-4000-8000-000000000001',('98020000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('98010000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'20000000-0000-4000-8000-000000000012','Immutable report example'from generate_series(1,2)i;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.release_marking(internal.mark_submission('98020000-0000-4000-8000-000000000001',0,'Native zero reviewed',1,0,true),1,false);
select internal.release_marking(internal.mark_submission('98020000-0000-4000-8000-000000000002',7,'Parent approved feedback',1,0,true),1,true);
select lives_ok($$select internal.list_current_native_results_scoped(1,null,'20000000-0000-4000-8000-000000000012')$$,'teacher can read one bounded selected learner report page');
select ok(not exists(select 1 from jsonb_array_elements(internal.list_current_native_results_scoped(100,null,'20000000-0000-4000-8000-000000000012')->'items')item where item->>'learnerId'<>'20000000-0000-4000-8000-000000000012'),'selected learner source filter enters native candidates before projection');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select ok(exists(select 1 from jsonb_array_elements(internal.list_current_native_results_scoped(100,null,'20000000-0000-4000-8000-000000000012')->'items')item where item->>'submissionId'='98020000-0000-4000-8000-000000000001'and item->'nativeResult'->>'score'='0'and item->>'feedback'='Native zero reviewed'and item?'evidenceId'and item?'referenceVersion'),'native zero remains verified with feedback and provenance');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);
select throws_ok($$select internal.list_current_native_results_scoped(25,null,'20000000-0000-4000-8000-000000000012')$$,'42501',null,'peer cannot select another learner report');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select ok(not exists(select 1 from jsonb_array_elements(internal.list_current_native_results_scoped(100,null,'20000000-0000-4000-8000-000000000012')->'items')item where item->>'submissionId'='98020000-0000-4000-8000-000000000001'),'unapproved numeric source is excluded from parent report');
select ok(exists(select 1 from jsonb_array_elements(internal.list_current_native_results_scoped(100,null,'20000000-0000-4000-8000-000000000012')->'items')item where item->>'submissionId'='98020000-0000-4000-8000-000000000002'and item->>'parentVisible'='true'),'approved exact child source is available to parent report');
select throws_ok($$select internal.list_current_native_results_scoped(25,null,'20000000-0000-4000-8000-000000000013')$$,'42501',null,'parent cannot select an unrelated learner report');
reset role;savepoint report_relationship_revoked;
update app.parent_relationships set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and parent_actor_id='20000000-0000-4000-8000-000000000072';
set local role cuevo_api;
select throws_ok($$select internal.list_current_native_results_scoped(25,null,'20000000-0000-4000-8000-000000000012')$$,'42501',null,'relationship revocation denies a fresh report read');
reset role;rollback to report_relationship_revoked;
select ok(not has_function_privilege('cuevo_worker','internal.list_current_native_results_scoped(integer,uuid,uuid)','EXECUTE')and not has_function_privilege('authenticated','internal.list_current_native_results_scoped(integer,uuid,uuid)','EXECUTE')and not has_function_privilege('cuevo_api','internal.list_parent_current_results_scoped(integer,uuid,uuid)','EXECUTE'),'report is private API-only and parent helper has no direct grant');
select*from finish();rollback;
